INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Martyr gardien', 'livre', 'fallen', '{"source":"livre","page":220,"name":"Martyr gardien","family":"fallen","kind":"Défi · Déchu","quote":"","description":"Les martyrs gardiens sont parmi les rares à être devenus des Déchus par choix. Voués à la protection d''un lieu ou d''un objet, ils se sont soumis à une momification volontaire, faisant de leur propre corps ce qui les lie. Leur affaire inachevée, c''est la défense éternelle de ce qu''ils ont juré de garder.","track":10,"difficulty":{"force":2,"will":2,"influence":2,"reason":1,"precision":0,"subterfuge":2},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"Le Martyr gardien se jette sur un Paria et lui inflige une blessure."},{"box":6,"text":"Le Martyr gardien déclenche l''effet du dé d''obscurité de votre choix."},{"box":9,"text":"Le Martyr gardien change de style de combat : la difficulté des tests de Précision passe à +1."},{"box":10,"text":"Le Martyr gardien remercie les Parias de l''avoir libéré de son serment. Chaque Paria guérit une blessure."}],"complications":[{"text":"Vous force à revivre son tourment en visions.","effect":"anger","bookEffect":"Anxiety"},{"text":"Murmure sans fin à vos oreilles.","effect":"exhaustion","bookEffect":null},{"text":"Apparaît sous les traits d''un être que vous avez perdu.","effect":"shame","bookEffect":null},{"text":"Fait passer sur vous le frisson de la mort, qui vous fait trembler.","effect":"fear","bookEffect":null},{"text":"Possède votre corps un bref instant.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous accuse de crimes que vous n''avez pas commis.","effect":"anger","bookEffect":"Anger"},{"text":"Vous lance des objets avec une force violente.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":5,"text":"Le Martyr gardien fait surgir des images de sa momification volontaire pour vous dissuader de continuer : tous les Parias doivent réussir un test de Volonté (6) ou cocher la peur."},{"min":7,"text":"Le Martyr gardien draine votre énergie vitale par sa seule présence : le Paria qui vient d''agir coche l''épuisement."},{"min":10,"text":"Le Martyr gardien vous charge et projette des objets par la seule force de sa volonté : le Paria qui vient d''agir coche une blessure."}]},"rules":["Un Martyr gardien est lié pour toujours à son propre cadavre et ne peut jamais devenir intangible."],"familyRules":[{"name":"Éthérés","text":"Les Déchus passent d''une forme physique à une forme intangible. Intangibles, ils traversent la matière : on ne peut pas les toucher, et ils ne peuvent pas vous toucher. Quand ils prennent une forme physique (en possédant un cadavre ou au contact du salpêtre), ils deviennent tangibles."},{"name":"Sensibles au salpêtre","text":"Exposé à la poudre de salpêtre, un Déchu intangible est forcé de se manifester sous forme physique."},{"name":"Affaire inachevée","text":"Chaque Déchu est retenu dans le monde des vivants par une affaire non résolue. La résoudre le fait disparaître aussitôt."},{"name":"Liés","text":"Les Déchus sont ancrés à un lieu ou à un objet précis. Si l''objet est détruit, le Déchu disparaît aussitôt."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Martyr gardien' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Lié', 'livre', 'fae', '{"source":"livre","page":224,"name":"Lié","family":"fae","kind":"Défi · Fée","quote":"","description":"Les liés sont des humains qui ont conclu de leur plein gré un pacte avec une Fée et ont reçu une part de son pouvoir. S''ils ont toujours l''apparence humaine, ils ne sont plus mus que par une avidité sans fin.","track":5,"difficulty":{"force":0,"will":1,"influence":1,"reason":1,"precision":0,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":5,"text":"Le Lié est brièvement possédé par la Fée qui l''a corrompu. Parlant par sa bouche, la Fée propose un pacte aux Parias : ils sauront toujours où elle se trouve, mais en échange elle verra et entendra par leurs sens. Ceux qui acceptent sauront où est la Fée, mais deviennent soumis aux règles spéciales « Pacte contraignant » et « Sens à distance »."}],"complications":[{"text":"Vous fait croire qu''elle a prévu chacun de vos gestes.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous vole votre souffle et l''enferme dans une boîte.","effect":"exhaustion","bookEffect":null},{"text":"Fouille votre esprit et révèle un secret.","effect":"shame","bookEffect":null},{"text":"Fait naître des illusions terrifiantes que vous seul voyez.","effect":"fear","bookEffect":null},{"text":"Crée des mirages qui vous font douter de vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Joue avec vous jusqu''à ce que vous perdiez votre sang-froid.","effect":"anger","bookEffect":"Anger"},{"text":"Use d''illusions pour vous pousser à vous blesser vous-même.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":7,"text":"Le Lié fait naître des illusions qui égarent vos sens : tous les Parias doivent réussir un test de Raison (6) ou cocher l''insécurité (Confusion)."},{"min":11,"text":"Le Lié se jette sur vous avec une vitesse et une force surnaturelles et vous inflige une blessure. Son corps, qui n''est pas fait pour endurer une telle force, se fissure et se tord à vue d''œil."}]},"rules":["Pacte contraignant : rompre un pacte conclu avec une Fée lui permet de vous infliger chaque jour une blessure ou un état, où que vous soyez.","Sens à distance : une Fée peut voir et entendre par les sens de toute personne avec qui elle a conclu un pacte. L''en empêcher le temps d''une scène demande de réussir un test de Volonté difficile (6)."],"familyRules":[{"name":"Vulnérables au fer froid","text":"Le fer froid brûle les Fées comme des braises et réduit de 1 la difficulté des tests visant à les blesser."},{"name":"Pacte contraignant","text":"Rompre un pacte conclu avec une Fée lui permet de vous infliger chaque jour une blessure ou un état, où que vous soyez."},{"name":"Forme trompeuse","text":"Les Fées peuvent prendre temporairement l''apparence d''une personne qu''elles ont déjà vue."},{"name":"Sens à distance","text":"Une Fée peut voir et entendre par les sens de toute personne avec qui elle a conclu un pacte. L''en empêcher le temps d''une scène demande de réussir un test de Volonté difficile (6)."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Lié' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Ravisseur', 'livre', 'fae', '{"source":"livre","page":225,"name":"Ravisseur","family":"fae","kind":"Défi · Fée","quote":"","description":"Les ravisseurs volent les nouveau-nés dans leur berceau et les remplacent par des changelins, identiques en apparence mais hostiles et impossibles à maîtriser. Quelque temps plus tard, ils reviennent voir les parents désespérés, qui pleurent l''amour perdu de leur enfant, et prétendent que le bébé est maudit. Ils proposent de « rendre » l''enfant, à condition que les parents acceptent d''exaucer plus tard leurs demandes.","track":9,"difficulty":{"force":0,"will":2,"influence":0,"reason":2,"precision":0,"subterfuge":2},"resistances":[],"vulnerabilities":[],"triggers":[],"complications":[{"text":"Vous fait croire qu''elle a prévu chacun de vos gestes.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous vole votre souffle et l''enferme dans une boîte.","effect":"exhaustion","bookEffect":null},{"text":"Fouille votre esprit et révèle un secret.","effect":"shame","bookEffect":null},{"text":"Fait naître des illusions terrifiantes que vous seul voyez.","effect":"fear","bookEffect":null},{"text":"Crée des mirages qui vous font douter de vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Joue avec vous jusqu''à ce que vous perdiez votre sang-froid.","effect":"anger","bookEffect":"Anger"},{"text":"Use d''illusions pour vous pousser à vous blesser vous-même.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Le Ravisseur déclenche une complication au choix de l''Obscurité."},{"min":9,"text":"Le Ravisseur fait naître des illusions qui égarent vos sens : tous les Parias doivent réussir un test de Raison (6) ou cocher l''insécurité (Confusion)."}]},"rules":["Démasquer un Ravisseur : toucher le changelin d''un Ravisseur avec du fer froid révèle aussitôt sa véritable forme : une énorme créature semblable à un fœtus, grotesque à voir mais inoffensive.","Résoudre ce défi : les réussites nécessaires pour achever ce défi ne se limitent pas à l''affrontement direct. Utilisez les premières réussites pour calmer les parents et les raisonner, celles du milieu de la piste pour raconter une enquête ou un plan visant à retrouver le Ravisseur et l''enfant, et les dernières pour l''affrontement final."],"familyRules":[{"name":"Vulnérables au fer froid","text":"Le fer froid brûle les Fées comme des braises et réduit de 1 la difficulté des tests visant à les blesser."},{"name":"Pacte contraignant","text":"Rompre un pacte conclu avec une Fée lui permet de vous infliger chaque jour une blessure ou un état, où que vous soyez."},{"name":"Forme trompeuse","text":"Les Fées peuvent prendre temporairement l''apparence d''une personne qu''elles ont déjà vue."},{"name":"Sens à distance","text":"Une Fée peut voir et entendre par les sens de toute personne avec qui elle a conclu un pacte. L''en empêcher le temps d''une scène demande de réussir un test de Volonté difficile (6)."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Ravisseur' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Murmure', 'livre', 'fae', '{"source":"livre","page":226,"name":"Murmure","family":"fae","kind":"Défi · Fée","quote":"","description":"Les murmures sont des fées immensément puissantes, passées maîtresses dans l''art d''exploiter l''avidité humaine pour asservir leurs victimes. Affronter un murmure, c''est souvent affronter aussi une horde de serviteurs dévoués, prêts à tout pour le protéger.","track":11,"difficulty":{"force":0,"will":2,"influence":2,"reason":2,"precision":1,"subterfuge":2},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"Le Murmure riposte ou s''en prend à un Paria, et lui inflige une blessure."},{"box":5,"text":"Le Murmure ordonne à ses serviteurs d''attaquer : tous les Parias doivent réussir un test de Force (5) ou cocher une blessure."},{"box":9,"text":"Le Murmure prend l''apparence de l''un de ses serviteurs. Désormais, si un Paria le frappe et obtient un résultat impair, il touche la mauvaise cible. Si le résultat est pair, l''effet prend fin."},{"box":11,"text":"Le Murmure propose de révéler un secret sur la vraie nature de l''Obscurité, mais en échange vous devez le laisser partir et accepter les effets des règles spéciales « Pacte contraignant » et « Sens à distance »."}],"complications":[{"text":"Vous fait croire qu''elle a prévu chacun de vos gestes.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous vole votre souffle et l''enferme dans une boîte.","effect":"exhaustion","bookEffect":null},{"text":"Fouille votre esprit et révèle un secret.","effect":"shame","bookEffect":null},{"text":"Fait naître des illusions terrifiantes que vous seul voyez.","effect":"fear","bookEffect":null},{"text":"Crée des mirages qui vous font douter de vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Joue avec vous jusqu''à ce que vous perdiez votre sang-froid.","effect":"anger","bookEffect":"Anger"},{"text":"Use d''illusions pour vous pousser à vous blesser vous-même.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":5,"text":"Le Murmure fait naître des illusions qui égarent vos sens : tous les Parias doivent réussir un test de Raison (6) ou cocher l''insécurité (Confusion)."},{"min":8,"text":"Le Murmure vous montre la souffrance de ceux qui le servent : le Paria qui vient d''agir coche la honte ou la colère (Anger), à son choix."},{"min":12,"text":"Le Murmure vole dans votre esprit un secret que vous tenez désespérément à cacher : le Paria qui vient d''agir révèle ce secret à l''Obscurité."}]},"rules":[],"familyRules":[{"name":"Vulnérables au fer froid","text":"Le fer froid brûle les Fées comme des braises et réduit de 1 la difficulté des tests visant à les blesser."},{"name":"Pacte contraignant","text":"Rompre un pacte conclu avec une Fée lui permet de vous infliger chaque jour une blessure ou un état, où que vous soyez."},{"name":"Forme trompeuse","text":"Les Fées peuvent prendre temporairement l''apparence d''une personne qu''elles ont déjà vue."},{"name":"Sens à distance","text":"Une Fée peut voir et entendre par les sens de toute personne avec qui elle a conclu un pacte. L''en empêcher le temps d''une scène demande de réussir un test de Volonté difficile (6)."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Murmure' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Défait', 'livre', 'ferals', '{"source":"livre","page":230,"name":"Défait","family":"ferals","kind":"Défi · Polymorphe","quote":"","description":"Ces êtres misérables sont prisonniers à mi-chemin entre leur forme humaine et leur forme bestiale. Leurs muscles et leurs tendons sont déchirés, leurs os de travers, leurs dents mi-humaines, mi-animales. Fous de douleur et rendus déments par la faim, ils se jettent à l''aveugle sur quiconque passe à leur portée.","track":6,"difficulty":{"force":2,"will":0,"influence":0,"reason":0,"precision":1,"subterfuge":0},"resistances":[],"vulnerabilities":[],"triggers":[{"box":6,"text":"Rendu fou par la douleur, le Défait se déchire la chair et s''arrache la carotide. Chaque Paria doit réussir un test de Volonté (6) ou cocher, à son choix, la colère (Anxiety) ou la peur."}],"complications":[{"text":"Est aveuglé par la rage et impossible à prévoir.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous plaque violemment au sol ; vous vous sentez engourdi.","effect":"exhaustion","bookEffect":null},{"text":"Croise un instant votre regard avec une expression humaine et terrifiée.","effect":"shame","bookEffect":null},{"text":"Vous regarde comme un morceau de viande.","effect":"fear","bookEffect":null},{"text":"Se déplace trop vite pour que vous puissiez le suivre.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous traque sans relâche, jusqu''à ce que votre instinct de survie prenne le dessus.","effect":"anger","bookEffect":"Anger"},{"text":"Déchire votre chair de ses crocs et de ses griffes.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":8,"text":"Le Défait se jette sur vous dans un tourbillon de crocs et de griffes : le Paria qui vient d''agir coche l''épuisement et une blessure."},{"min":12,"text":"Le Défait vous mord et vous retient entre ses mâchoires : le Paria qui vient d''agir coche une blessure et doit réussir un test de Force (5) pour se dégager ; sinon, il devra refaire ce test au début de son prochain tour pour éviter une nouvelle blessure."}]},"rules":[],"familyRules":[{"name":"Vulnérables à l''argent","text":"L''argent est le seul métal capable d''infliger des blessures qu''un Polymorphe ne peut pas régénérer. En outre, la difficulté des tests visant à blesser un Polymorphe avec une arme d''argent ou d''argentacier est réduite de 1."},{"name":"Régénération","text":"Les Polymorphes guérissent rapidement de toute blessure infligée par une arme ordinaire. À la fin de chaque tour, effacez toutes les blessures causées par ces armes. Les blessures dues à l''argent, à l''argentacier, aux dons et aux sombres héritages ne se régénèrent jamais."},{"name":"Rage","text":"Sous leur forme bestiale, les Polymorphes agissent en purs prédateurs. Impossible de raisonner avec eux : tout test visant à les raisonner entraîne automatiquement une complication."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Défait' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Prédateur', 'livre', 'ferals', '{"source":"livre","page":231,"name":"Prédateur","family":"ferals","kind":"Défi · Polymorphe","quote":"","description":"Les prédateurs sont des Polymorphes dans leur forme achevée. Humains la plupart du temps, ils se transforment sous la lune en bêtes terrifiantes avides de chair humaine. Leur force est presque irrésistible, leur faim jamais rassasiée.","track":8,"difficulty":{"force":2,"will":1,"influence":0,"reason":0,"precision":2,"subterfuge":0},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"Le Prédateur pousse un son à mi-chemin entre le hurlement et le grondement : tous les Parias doivent réussir un test de Volonté (5) ou cocher la peur."},{"box":6,"text":"Le Prédateur soulève un Paria et le projette contre un autre avec une force brutale : tous deux cochent une blessure."}],"complications":[{"text":"Est aveuglé par la rage et impossible à prévoir.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous plaque violemment au sol ; vous vous sentez engourdi.","effect":"exhaustion","bookEffect":null},{"text":"Croise un instant votre regard avec une expression humaine et terrifiée.","effect":"shame","bookEffect":null},{"text":"Vous regarde comme un morceau de viande.","effect":"fear","bookEffect":null},{"text":"Se déplace trop vite pour que vous puissiez le suivre.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous traque sans relâche, jusqu''à ce que votre instinct de survie prenne le dessus.","effect":"anger","bookEffect":"Anger"},{"text":"Déchire votre chair de ses crocs et de ses griffes.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Le Prédateur pare chaque coup sans vous laisser de répit : le Paria qui vient d''agir coche l''épuisement."},{"min":8,"text":"Le Prédateur vous charge dans un déluge de crocs et de griffes : le Paria qui vient d''agir coche la peur et une blessure."},{"min":12,"text":"Le Prédateur vous mord et vous retient entre ses mâchoires : le Paria qui vient d''agir coche une blessure et doit réussir un test de Force (5) pour se dégager ; sinon, il devra refaire ce test au début de son prochain tour pour éviter une nouvelle blessure."}]},"rules":["Forme humaine : lorsqu''il n''est pas transformé, un Polymorphe ne se distingue pas d''un humain ordinaire. On peut l''emprisonner, voire le tuer, avec 1 réussite. Il ne garde aucun souvenir de sa transformation, même s''il peut s''en douter à l''état dans lequel il se retrouve."],"familyRules":[{"name":"Vulnérables à l''argent","text":"L''argent est le seul métal capable d''infliger des blessures qu''un Polymorphe ne peut pas régénérer. En outre, la difficulté des tests visant à blesser un Polymorphe avec une arme d''argent ou d''argentacier est réduite de 1."},{"name":"Régénération","text":"Les Polymorphes guérissent rapidement de toute blessure infligée par une arme ordinaire. À la fin de chaque tour, effacez toutes les blessures causées par ces armes. Les blessures dues à l''argent, à l''argentacier, aux dons et aux sombres héritages ne se régénèrent jamais."},{"name":"Rage","text":"Sous leur forme bestiale, les Polymorphes agissent en purs prédateurs. Impossible de raisonner avec eux : tout test visant à les raisonner entraîne automatiquement une complication."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Prédateur' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Amalgame', 'livre', 'ferals', '{"source":"livre","page":232,"name":"Amalgame","family":"ferals","kind":"Défi · Polymorphe","quote":"","description":"Certains Polymorphes se sont transformés tant de fois qu''ils ont perdu toute trace d''humanité. Un amalgame est une masse de chair, de crocs, d''os et de griffes. Son anatomie est à peine discernable, et seule la férocité l''anime.","track":11,"difficulty":{"force":3,"will":1,"influence":1,"reason":0,"precision":2,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":1,"text":"L''Amalgame se tord et se convulse horriblement devant vous : tous les Parias doivent réussir un test de Volonté (6) ou cocher la peur."},{"box":5,"text":"L''Amalgame pose sur vous l''un de ses nombreux yeux. C''est un œil humain, en larmes et plein de terreur : le Paria qui vient d''agir coche la colère (Anxiety) et l''insécurité (Confusion)."},{"box":9,"text":"L''Amalgame se divise en plusieurs masses distinctes : la difficulté des tests de Subterfuge passe à +2."}],"complications":[{"text":"Est aveuglé par la rage et impossible à prévoir.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous plaque violemment au sol ; vous vous sentez engourdi.","effect":"exhaustion","bookEffect":null},{"text":"Croise un instant votre regard avec une expression humaine et terrifiée.","effect":"shame","bookEffect":null},{"text":"Vous regarde comme un morceau de viande.","effect":"fear","bookEffect":null},{"text":"Se déplace trop vite pour que vous puissiez le suivre.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous traque sans relâche, jusqu''à ce que votre instinct de survie prenne le dessus.","effect":"anger","bookEffect":"Anger"},{"text":"Déchire votre chair de ses crocs et de ses griffes.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"L''Amalgame vous presse de ses crocs et de ses griffes : le Paria qui vient d''agir coche l''épuisement."},{"min":8,"text":"L''Amalgame roule vers vous, ses membres acérés en avant : le Paria qui vient d''agir coche la peur et une blessure."},{"min":12,"text":"L''Amalgame vous saisit et vous serre fort : le Paria qui vient d''agir coche une blessure et doit réussir un test de Force (5) pour se dégager ; sinon, il devra refaire ce test au début de son prochain tour pour éviter une nouvelle blessure."}]},"rules":[],"familyRules":[{"name":"Vulnérables à l''argent","text":"L''argent est le seul métal capable d''infliger des blessures qu''un Polymorphe ne peut pas régénérer. En outre, la difficulté des tests visant à blesser un Polymorphe avec une arme d''argent ou d''argentacier est réduite de 1."},{"name":"Régénération","text":"Les Polymorphes guérissent rapidement de toute blessure infligée par une arme ordinaire. À la fin de chaque tour, effacez toutes les blessures causées par ces armes. Les blessures dues à l''argent, à l''argentacier, aux dons et aux sombres héritages ne se régénèrent jamais."},{"name":"Rage","text":"Sous leur forme bestiale, les Polymorphes agissent en purs prédateurs. Impossible de raisonner avec eux : tout test visant à les raisonner entraîne automatiquement une complication."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Amalgame' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Succube', 'livre', 'hexed', '{"source":"livre","page":236,"name":"Succube","family":"hexed","kind":"Défi · Maudit","quote":"","description":"Parmi ceux qui s''abandonnent à l''Obscurité, les succubes sont les plus vils. Malveillants et fourbes, ils renoncent à leur humanité en échange de miettes de pouvoir.","track":5,"difficulty":{"force":0,"will":1,"influence":0,"reason":1,"precision":0,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"Le Succube enveloppe les lieux d''une brume impénétrable : la difficulté des tests reposant sur la vue augmente de 1."},{"box":4,"text":"Le Succube tente de fuir. Si les Parias n''obtiennent pas la 5e réussite d''ici la fin de leur prochain tour, il s''échappe."}],"complications":[{"text":"Vous jette un mauvais œil qui vous promet une vie de souffrance.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous inflige un maléfice qui vous laisse faible et malade.","effect":"exhaustion","bookEffect":null},{"text":"Voit votre culpabilité et vous convainc que les autres ne voient qu''elle en vous.","effect":"shame","bookEffect":null},{"text":"Vous prédit un terrible présage.","effect":"fear","bookEffect":null},{"text":"Brouille vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous rappelle que votre destin est scellé et que vous en êtes l''esclave.","effect":"anger","bookEffect":"Anger"},{"text":"Attire sur vous un événement désastreux.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Le Succube libère une vague d''énergie ténébreuse : tous les Parias cochent l''épuisement et doivent réussir un test de Volonté (5) ou cocher une blessure."},{"min":10,"text":"Le Succube invoque une nuée de corbeaux ou d''insectes qui vous assaille : tous les Parias doivent réussir un test de Précision ou de Force (5) ou cocher une blessure."}]},"rules":[],"familyRules":[{"name":"Vulnérables aux symboles sacrés","text":"Les Maudits abhorrent les symboles sacrés de toute sorte, pas seulement ceux du luminarisme, pourvu qu''ils aient été créés par de vrais croyants. Quand ils y sont exposés, la difficulté de tous les tests contre eux est réduite de 1."},{"name":"Aura de ruine","text":"La présence d''un Maudit attire le mauvais sort. Tout ce qui peut mal tourner tourne mal, de la pire façon possible. Égaler la difficulté d''un test contre un Maudit ne donne pas une réussite avec complication, mais seulement une complication."},{"name":"Destin marqué","text":"Vous pouvez mettre de côté jusqu''à 3 complications causées par des tests contre un Maudit et les faire jouer plus tard, quand vous le souhaitez."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Succube' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Mégère', 'livre', 'hexed', '{"source":"livre","page":237,"name":"Mégère","family":"hexed","kind":"Défi · Maudit","quote":"","description":"Ces créatures rusées et cruelles vivent pour ruiner la vie d''individus ou de communautés entières. Autrefois humaines, les mégères sont animées par la rancœur et la haine envers ceux qui les ont rejetées, maltraitées et isolées. Devenues les monstres qu''on les accusait jadis d''être, elles n''aspirent plus qu''à la vengeance.","track":8,"difficulty":{"force":0,"will":2,"influence":1,"reason":1,"precision":0,"subterfuge":2},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"La Mégère enveloppe les lieux d''une brume impénétrable : la difficulté des tests reposant sur la vue augmente de 1."},{"box":6,"text":"La Mégère libère une vague d''énergie ténébreuse : chaque Paria coche l''épuisement et doit réussir un test de Volonté (6) ou cocher une blessure."},{"box":8,"text":"Juste avant de mourir, la Mégère maudit le Paria qui lui a porté le coup fatal : l''Obscurité gagne une complication qu''elle pourra utiliser contre lui à tout moment par la suite."}],"complications":[{"text":"Vous jette un mauvais œil qui vous promet une vie de souffrance.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous inflige un maléfice qui vous laisse faible et malade.","effect":"exhaustion","bookEffect":null},{"text":"Voit votre culpabilité et vous convainc que les autres ne voient qu''elle en vous.","effect":"shame","bookEffect":null},{"text":"Vous prédit un terrible présage.","effect":"fear","bookEffect":null},{"text":"Brouille vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous rappelle que votre destin est scellé et que vous en êtes l''esclave.","effect":"anger","bookEffect":"Anger"},{"text":"Attire sur vous un événement désastreux.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":7,"text":"La Mégère détourne votre attention : le Paria qui vient d''agir doit réussir un test de Raison ou de Subterfuge (5) ou cocher l''insécurité (Confusion)."},{"min":10,"text":"La Mégère invoque une nuée de corbeaux ou d''insectes qui vous assaille : tous les Parias doivent réussir un test de Précision ou de Force (5) ou cocher une blessure."}]},"rules":[],"familyRules":[{"name":"Vulnérables aux symboles sacrés","text":"Les Maudits abhorrent les symboles sacrés de toute sorte, pas seulement ceux du luminarisme, pourvu qu''ils aient été créés par de vrais croyants. Quand ils y sont exposés, la difficulté de tous les tests contre eux est réduite de 1."},{"name":"Aura de ruine","text":"La présence d''un Maudit attire le mauvais sort. Tout ce qui peut mal tourner tourne mal, de la pire façon possible. Égaler la difficulté d''un test contre un Maudit ne donne pas une réussite avec complication, mais seulement une complication."},{"name":"Destin marqué","text":"Vous pouvez mettre de côté jusqu''à 3 complications causées par des tests contre un Maudit et les faire jouer plus tard, quand vous le souhaitez."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Mégère' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Sorcière', 'livre', 'hexed', '{"source":"livre","page":238,"name":"Sorcière","family":"hexed","kind":"Défi · Maudit","quote":"","description":"Les sorcières sont si anciennes et si puissantes qu''il ne reste plus en elles aucune trace d''humanité. Leur seule présence peut gâter les récoltes, rendre malades des villages entiers et plonger les gens dans le désespoir.","track":11,"difficulty":{"force":0,"will":3,"influence":2,"reason":1,"precision":0,"subterfuge":3},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"La Sorcière enveloppe les lieux d''une brume impénétrable : la difficulté des tests reposant sur la vue augmente de 1."},{"box":5,"text":"La Sorcière libère une vague d''énergie ténébreuse : tous les Parias cochent l''épuisement et doivent réussir un test de Volonté (6) ou cocher une blessure."},{"box":9,"text":"La Sorcière se fond parfaitement dans le décor et devient totalement invisible."},{"box":11,"text":"La Sorcière vous maudit avant de mourir : l''Obscurité gagne 1 complication par Paria, qu''elle pourra utiliser à tout moment par la suite."}],"complications":[{"text":"Vous jette un mauvais œil qui vous promet une vie de souffrance.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous inflige un maléfice qui vous laisse faible et malade.","effect":"exhaustion","bookEffect":null},{"text":"Voit votre culpabilité et vous convainc que les autres ne voient qu''elle en vous.","effect":"shame","bookEffect":null},{"text":"Vous prédit un terrible présage.","effect":"fear","bookEffect":null},{"text":"Brouille vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous rappelle que votre destin est scellé et que vous en êtes l''esclave.","effect":"anger","bookEffect":"Anger"},{"text":"Attire sur vous un événement désastreux.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":7,"text":"La Sorcière détourne votre attention : le Paria qui vient d''agir doit réussir un test de Raison (5) ou cocher l''insécurité (Confusion)."},{"min":10,"text":"La Sorcière invoque une nuée de corbeaux ou d''insectes qui vous assaille : tous les Parias doivent réussir un test de Précision ou de Force (5) ou cocher une blessure."},{"min":12,"text":"La Sorcière dévore une part de vous : le Paria qui vient d''agir doit réussir un test de Volonté (6) ou effacer un trait de personnalité. Il pourra en écrire un nouveau au même endroit plus tard, mais cette part de lui ne reviendra jamais."}]},"rules":[],"familyRules":[{"name":"Vulnérables aux symboles sacrés","text":"Les Maudits abhorrent les symboles sacrés de toute sorte, pas seulement ceux du luminarisme, pourvu qu''ils aient été créés par de vrais croyants. Quand ils y sont exposés, la difficulté de tous les tests contre eux est réduite de 1."},{"name":"Aura de ruine","text":"La présence d''un Maudit attire le mauvais sort. Tout ce qui peut mal tourner tourne mal, de la pire façon possible. Égaler la difficulté d''un test contre un Maudit ne donne pas une réussite avec complication, mais seulement une complication."},{"name":"Destin marqué","text":"Vous pouvez mettre de côté jusqu''à 3 complications causées par des tests contre un Maudit et les faire jouer plus tard, quand vous le souhaitez."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Sorcière' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Incube', 'livre', 'shadows', '{"source":"livre","page":242,"name":"Incube","family":"shadows","kind":"Défi · Ombre","quote":"","description":"Les incubes sont des créatures sournoises et répugnantes qui, la nuit, rampent sur la poitrine des dormeurs, provoquent d''horribles visions et se nourrissent de leur terreur. S''il est rare qu''un incube tue quelqu''un, sa présence peut pousser ses victimes au bord de la folie.","track":5,"difficulty":{"force":0,"will":1,"influence":0,"reason":0,"precision":1,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"L''incube réveille la personne qu''il hante, qui se débat, prise de panique. Les tests contre elle sont faciles (4), mais elle tente d''attaquer tous ceux qu''elle voit."}],"complications":[{"text":"Vous murmure sans cesse à l''oreille, nourrissant votre paranoïa.","effect":"anger","bookEffect":"Anxiety"},{"text":"Fait chuter la température et vous glace jusqu''aux os.","effect":"exhaustion","bookEffect":null},{"text":"Vous rappelle vos erreurs les plus douloureuses.","effect":"shame","bookEffect":null},{"text":"Se manifeste sous la forme de ce que vous craignez le plus.","effect":"fear","bookEffect":null},{"text":"Voile la réalité et brouille vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Se moque de vous et ricane depuis le néant d''où elle est venue.","effect":"anger","bookEffect":"Anger"},{"text":"Se matérialise en vrille et vous frappe.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":8,"text":"L''incube bondit sur vous et son contact froid vous glace jusqu''aux os : le Paria qui vient d''agir coche une blessure."},{"min":11,"text":"L''incube s''agrippe à vous et déchaîne cauchemars et hallucinations : le Paria qui vient d''agir coche la peur et doit réussir un test de Volonté difficile (6), ou cocher aussi la colère (Anxiety)."}]},"rules":[],"familyRules":[{"name":"Sensibles à la verlume","text":"La verlume affaiblit les Ombres : elle réduit de 1 la difficulté de tous les tests contre elles."},{"name":"Froid, trop froid","text":"La température baisse en présence des Ombres, et chute brutalement quand elles gagnent en puissance."},{"name":"Informes","text":"Les Ombres n''ont que deux dimensions et peuvent se glisser par les fissures les plus étroites."},{"name":"Semi-solides","text":"Bien qu''elles n''aient pas de forme fixe, les Ombres restent tangibles : elles peuvent agir physiquement sur le monde, et le monde peut agir sur elles."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Incube' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Marionnettiste', 'livre', 'shadows', '{"source":"livre","page":243,"name":"Marionnettiste","family":"shadows","kind":"Défi · Ombre","quote":"","description":"Nés d''un traumatisme infligé à une âme innocente, les marionnettistes prennent forme dans l''ombre de leur victime et s''emparent de son corps comme d''une marionnette sans vie. Ils forcent leur hôte à revivre les sévices subis, attirant de nouveaux bourreaux qui ignorent tomber dans un piège. Une fois que l''appât a servi, l''Ombre se révèle et dévore les coupables. Si cela peut ressembler à une forme tordue de vengeance, les marionnettistes ne libèrent jamais leurs marionnettes. Ils les consument lentement, les vidant jour après jour jusqu''à ce qu''elles meurent d''épuisement.","track":7,"difficulty":{"force":0,"will":2,"influence":0,"reason":1,"precision":0,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"Le marionnettiste répand dans l''air un froid surnaturel : tous les Parias doivent réussir un test de Volonté difficile (6) ou cocher l''épuisement."},{"box":6,"text":"Le marionnettiste force sa marionnette à porter un objet tranchant à sa propre gorge."}],"complications":[{"text":"Vous murmure sans cesse à l''oreille, nourrissant votre paranoïa.","effect":"anger","bookEffect":"Anxiety"},{"text":"Fait chuter la température et vous glace jusqu''aux os.","effect":"exhaustion","bookEffect":null},{"text":"Vous rappelle vos erreurs les plus douloureuses.","effect":"shame","bookEffect":null},{"text":"Se manifeste sous la forme de ce que vous craignez le plus.","effect":"fear","bookEffect":null},{"text":"Voile la réalité et brouille vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Se moque de vous et ricane depuis le néant d''où elle est venue.","effect":"anger","bookEffect":"Anger"},{"text":"Se matérialise en vrille et vous frappe.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":7,"text":"Le marionnettiste parle avec la voix de sa marionnette et implore pitié : tous les Parias doivent réussir un test de Volonté difficile (6) ou cocher, au choix, la colère (Anxiety), l''insécurité (Confusion) ou la honte."},{"min":10,"text":"Le marionnettiste déchaîne une tempête de vrilles et de griffes d''ombre : tous les Parias doivent réussir un test de Précision difficile (6) ou cocher une blessure."}]},"rules":["Le chemin le plus difficile : tuer la marionnette ne demande qu''une seule réussite et détruit aussitôt le marionnettiste. Mener le défi à son terme sans tuer la marionnette élimine le marionnettiste et libère la victime de son emprise."],"familyRules":[{"name":"Sensibles à la verlume","text":"La verlume affaiblit les Ombres : elle réduit de 1 la difficulté de tous les tests contre elles."},{"name":"Froid, trop froid","text":"La température baisse en présence des Ombres, et chute brutalement quand elles gagnent en puissance."},{"name":"Informes","text":"Les Ombres n''ont que deux dimensions et peuvent se glisser par les fissures les plus étroites."},{"name":"Semi-solides","text":"Bien qu''elles n''aient pas de forme fixe, les Ombres restent tangibles : elles peuvent agir physiquement sur le monde, et le monde peut agir sur elles."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Marionnettiste' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Famine', 'livre', 'shadows', '{"source":"livre","page":244,"name":"Famine","family":"shadows","kind":"Défi · Ombre","quote":"","description":"Les famines sont de puissantes Ombres qui hantent de vastes zones habitées, font lentement baisser la température et se nourrissent du désespoir de leurs victimes. Ceux qui se trouvent à leur portée sont tourmentés par le froid, la paranoïa et la faim, et meurent à petit feu tandis que la famine se renforce sans cesse.","track":4,"difficulty":{"force":0,"will":1,"influence":1,"reason":1,"precision":0,"subterfuge":0},"resistances":[],"vulnerabilities":[],"triggers":[{"box":1,"text":"La famine fait chuter brutalement la température et répand la paranoïa : la difficulté de tous les tests augmente de 1."},{"box":2,"text":"La famine fait chuter brutalement la température et répand la paranoïa : la difficulté de tous les tests augmente de 1."},{"box":3,"text":"La famine fait chuter brutalement la température et répand la paranoïa : la difficulté de tous les tests augmente de 1."},{"box":4,"text":"La famine fait chuter brutalement la température et répand la paranoïa : la difficulté de tous les tests augmente de 1."}],"complications":[{"text":"Vous murmure sans cesse à l''oreille, nourrissant votre paranoïa.","effect":"anger","bookEffect":"Anxiety"},{"text":"Fait chuter la température et vous glace jusqu''aux os.","effect":"exhaustion","bookEffect":null},{"text":"Vous rappelle vos erreurs les plus douloureuses.","effect":"shame","bookEffect":null},{"text":"Se manifeste sous la forme de ce que vous craignez le plus.","effect":"fear","bookEffect":null},{"text":"Voile la réalité et brouille vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Se moque de vous et ricane depuis le néant d''où elle est venue.","effect":"anger","bookEffect":"Anger"},{"text":"Se matérialise en vrille et vous frappe.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"La famine influence les habitants de la zone infestée et les retourne contre vous."}]},"rules":["Les quatre foyers : chaque famine ancre son essence dans quatre objets cachés dans la zone qu''elle hante, qu''il faut détruire pour mener le défi à son terme.","Localiser un foyer : Obscurité, demandez des tests d''enquête entre un foyer et le suivant. Faites monter la tension et soulignez la paranoïa grandissante.","Identifier les foyers : chaque foyer dégage un froid si intense qu''il inflige une blessure à quiconque le touche sans se couvrir les mains. Les foyers sont souvent liés à des événements traumatiques : l''arme d''un meurtre, une lettre d''adieu…","Détruire un foyer : détruire un foyer demande un test normal (5), mais déclenche toujours un effet et augmente la difficulté pour détruire le suivant.","Rassembler les foyers : les Parias peuvent réunir plusieurs foyers et les détruire tous à la fois, même s''ils ne s''en rendent pas forcément compte tout de suite."],"familyRules":[{"name":"Sensibles à la verlume","text":"La verlume affaiblit les Ombres : elle réduit de 1 la difficulté de tous les tests contre elles."},{"name":"Froid, trop froid","text":"La température baisse en présence des Ombres, et chute brutalement quand elles gagnent en puissance."},{"name":"Informes","text":"Les Ombres n''ont que deux dimensions et peuvent se glisser par les fissures les plus étroites."},{"name":"Semi-solides","text":"Bien qu''elles n''aient pas de forme fixe, les Ombres restent tangibles : elles peuvent agir physiquement sur le monde, et le monde peut agir sur elles."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Famine' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Sang-Neuf', 'livre', 'vampires', '{"source":"livre","page":248,"name":"Sang-Neuf","family":"vampires","kind":"Défi · Vampire","quote":"","description":"Ces Vampires n''ont été transformés que récemment et se cramponnent encore à l''identité qu''ils avaient de leur vivant. Ce sont des créatures rusées qui, acculées, deviennent agressives et dangereuses.","track":6,"difficulty":{"force":1,"will":1,"influence":0,"reason":0,"precision":1,"subterfuge":0},"resistances":[],"vulnerabilities":[],"triggers":[{"box":5,"text":"Le Sang-Neuf tente de fuir. Si les Parias n''obtiennent pas la 6e réussite d''ici la fin de leur prochain tour, il s''échappe."}],"complications":[{"text":"Joue avec votre esprit et vous emplit de doute et de soupçon.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous pourchasse à une vitesse inhumaine jusqu''à l''épuisement.","effect":"exhaustion","bookEffect":null},{"text":"Vous fixe d''un regard séducteur qui vous captive un instant.","effect":"shame","bookEffect":null},{"text":"Vous pétrifie sur place par sa présence terrifiante.","effect":"fear","bookEffect":null},{"text":"Brouille vos sens de son regard magnétique.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Se glisse dans votre esprit.","effect":"anger","bookEffect":"Anger"},{"text":"Frappe avec une précision affûtée par des siècles de mise à mort.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":8,"text":"Le Sang-Neuf se change en nuée de chauves-souris : tous les Parias doivent réussir un test de Volonté difficile (6) ou cocher l''insécurité (Confusion)."},{"min":12,"text":"Le Sang-Neuf vous mord et boit votre sang, se nourrissant de votre force vitale : le Paria qui vient d''agir coche l''épuisement et une blessure."}]},"rules":[],"familyRules":[{"name":"Morts-vivants","text":"Les Vampires n''ont pas de métabolisme. Ils sont immunisés contre les maladies et les poisons, et n''ont besoin ni de nourriture ni d''eau."},{"name":"Vulnérables à la lumière du soleil","text":"Un tour complet d''exposition à la lumière directe du soleil tue un Vampire sur le coup. Dommage que le soleil soit voilé par l''Obscurité ! Peut-être les Parias trouveront-ils un moyen d''y remédier."},{"name":"Soif de sang","text":"Un Vampire qui ne boit pas de sang pendant une journée entière s''affaiblit (-1 à la difficulté de tous ses tests). Au bout d''une semaine, il souffre de douleurs atroces. Au bout d''un mois, il sombre dans un état catatonique et reste inconscient jusqu''à ce qu''il parvienne, d''une manière ou d''une autre, à se nourrir de nouveau."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Sang-Neuf' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Sang-Noble', 'livre', 'vampires', '{"source":"livre","page":249,"name":"Sang-Noble","family":"vampires","kind":"Défi · Vampire","quote":"","description":"Les Sangs-Nobles sont Vampires depuis des décennies. Raffinés et puissants, ils ont une compréhension plus profonde de leurs pouvoirs et de leurs instincts. Calculateurs et jamais imprudents, ce sont des adversaires redoutables, physiquement comme mentalement.","track":9,"difficulty":{"force":0,"will":1,"influence":1,"reason":1,"precision":1,"subterfuge":2},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"Le Sang-Noble riposte : il se jette sur un Paria et lui inflige une blessure."},{"box":6,"text":"Le Sang-Noble active l''effet de dé d''obscurité de votre choix."},{"box":8,"text":"Le Sang-Noble tente de fuir. Si les Parias n''obtiennent pas la 9e réussite d''ici la fin de leur prochain tour, il s''échappe."}],"complications":[{"text":"Joue avec votre esprit et vous emplit de doute et de soupçon.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous pourchasse à une vitesse inhumaine jusqu''à l''épuisement.","effect":"exhaustion","bookEffect":null},{"text":"Vous fixe d''un regard séducteur qui vous captive un instant.","effect":"shame","bookEffect":null},{"text":"Vous pétrifie sur place par sa présence terrifiante.","effect":"fear","bookEffect":null},{"text":"Brouille vos sens de son regard magnétique.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Se glisse dans votre esprit.","effect":"anger","bookEffect":"Anger"},{"text":"Frappe avec une précision affûtée par des siècles de mise à mort.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Le Sang-Noble se change en nuée de chauves-souris : tous les Parias doivent réussir un test de Volonté difficile (6) ou cocher l''insécurité (Confusion)."},{"min":8,"text":"Le Sang-Noble vous mord et boit votre sang, se nourrissant de votre force vitale : le Paria qui vient d''agir coche l''épuisement et une blessure."},{"min":12,"text":"Le Sang-Noble se dissout en une forme semblable à une brume et devient intangible : jusqu''à la fin du prochain tour, toute interaction physique avec lui est impossible."}]},"rules":[],"familyRules":[{"name":"Morts-vivants","text":"Les Vampires n''ont pas de métabolisme. Ils sont immunisés contre les maladies et les poisons, et n''ont besoin ni de nourriture ni d''eau."},{"name":"Vulnérables à la lumière du soleil","text":"Un tour complet d''exposition à la lumière directe du soleil tue un Vampire sur le coup. Dommage que le soleil soit voilé par l''Obscurité ! Peut-être les Parias trouveront-ils un moyen d''y remédier."},{"name":"Soif de sang","text":"Un Vampire qui ne boit pas de sang pendant une journée entière s''affaiblit (-1 à la difficulté de tous ses tests). Au bout d''une semaine, il souffre de douleurs atroces. Au bout d''un mois, il sombre dans un état catatonique et reste inconscient jusqu''à ce qu''il parvienne, d''une manière ou d''une autre, à se nourrir de nouveau."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Sang-Noble' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Sang-Ancien', 'livre', 'vampires', '{"source":"livre","page":250,"name":"Sang-Ancien","family":"vampires","kind":"Défi · Vampire","quote":"","description":"Les Sangs-Anciens sont l''expression suprême du pouvoir vampirique. Ils ont vu des empires naître et tomber ; à leurs yeux, une vie humaine n''est qu''un battement de cils. Leur chair est de marbre, leur cœur de pierre, leur non-vie est le sang.","track":12,"difficulty":{"force":1,"will":1,"influence":2,"reason":1,"precision":2,"subterfuge":2},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"Le Sang-Ancien riposte : il se jette sur un Paria et lui inflige une blessure."},{"box":5,"text":"Le Sang-Ancien active l''effet de dé d''obscurité de votre choix."},{"box":9,"text":"Le Sang-Ancien se change en un gigantesque monstre chiroptère : le modificateur de tous les tests de Force et de Volonté passe désormais à +2."},{"box":11,"text":"Le Sang-Ancien rit de plaisir, ravi de se sentir de nouveau mis au défi : tous les Parias cochent la peur."}],"complications":[{"text":"Joue avec votre esprit et vous emplit de doute et de soupçon.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous pourchasse à une vitesse inhumaine jusqu''à l''épuisement.","effect":"exhaustion","bookEffect":null},{"text":"Vous fixe d''un regard séducteur qui vous captive un instant.","effect":"shame","bookEffect":null},{"text":"Vous pétrifie sur place par sa présence terrifiante.","effect":"fear","bookEffect":null},{"text":"Brouille vos sens de son regard magnétique.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Se glisse dans votre esprit.","effect":"anger","bookEffect":"Anger"},{"text":"Frappe avec une précision affûtée par des siècles de mise à mort.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":4,"text":"Le Sang-Ancien se change en nuée de chauves-souris : tous les Parias doivent réussir un test de Volonté difficile (6) ou cocher l''insécurité (Confusion)."},{"min":6,"text":"Le Sang-Ancien vous mord et boit votre sang, se nourrissant de votre force vitale : le Paria qui vient d''agir coche l''épuisement et une blessure."},{"min":8,"text":"Le Sang-Ancien se dissout en une forme semblable à une brume et devient intangible : jusqu''à la fin du prochain tour, toute interaction physique avec lui est impossible."},{"min":12,"text":"Le Sang-Ancien se glisse dans l''esprit d''un Paria et éveille sa pulsion."}]},"rules":[],"familyRules":[{"name":"Morts-vivants","text":"Les Vampires n''ont pas de métabolisme. Ils sont immunisés contre les maladies et les poisons, et n''ont besoin ni de nourriture ni d''eau."},{"name":"Vulnérables à la lumière du soleil","text":"Un tour complet d''exposition à la lumière directe du soleil tue un Vampire sur le coup. Dommage que le soleil soit voilé par l''Obscurité ! Peut-être les Parias trouveront-ils un moyen d''y remédier."},{"name":"Soif de sang","text":"Un Vampire qui ne boit pas de sang pendant une journée entière s''affaiblit (-1 à la difficulté de tous ses tests). Au bout d''une semaine, il souffre de douleurs atroces. Au bout d''un mois, il sombre dans un état catatonique et reste inconscient jusqu''à ce qu''il parvienne, d''une manière ou d''une autre, à se nourrir de nouveau."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Sang-Ancien' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Troll', 'livre', 'wildkin', '{"source":"livre","page":254,"name":"Troll","family":"wildkin","kind":"Défi · Sylvestre","quote":"","description":"Les trolls hantent les lieux de passage, comme les carrefours isolés et les vieux ponts, où ils restent à l''affût. Dotés d''une force terrifiante et d''une intelligence cruelle, ils tendent des embuscades aux voyageurs, les dévorent et amassent leurs biens comme de macabres trophées.","track":5,"difficulty":{"force":1,"will":0,"influence":0,"reason":1,"precision":0,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":1,"text":"Le troll prononce une énigme discordante dans une langue ancienne : tous les Parias doivent réussir un test de Raison ou de Subterfuge normal (5) ou cocher l''insécurité (Confusion)."},{"box":4,"text":"Le troll entre dans une rage violente et implacable : le modificateur des tests de Force augmente de +2."}],"complications":[{"text":"Se fond dans la végétation : il pourrait être n''importe où.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous écrase et vous vide de vos forces.","effect":"exhaustion","bookEffect":null},{"text":"Vous force à voir à quel point l''humanité a souillé son domaine.","effect":"shame","bookEffect":null},{"text":"Se révèle dans toute sa grandeur antique.","effect":"fear","bookEffect":null},{"text":"Emplit vos poumons de toxines psychotropes.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Détruit quelque chose qui vous est cher.","effect":"anger","bookEffect":"Anger"},{"text":"Se jette violemment sur vous.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Le troll projette sur vous un rocher ou une poutre : tous les Parias doivent réussir un test de Précision ou de Force normal (5) ou cocher une blessure."},{"min":10,"text":"Le troll fait surgir des racines qui vous entravent les jambes : le Paria qui vient d''agir coche une blessure et doit réussir un test de Précision normal (5), sans quoi il ne pourra pas quitter sa position actuelle au prochain tour."}]},"rules":[],"familyRules":[{"name":"Faiblesse face au feu","text":"Les Sylvestres craignent le feu et en souffrent plus que toute autre créature. L''utiliser réduit de 1 la difficulté de tous les tests contre eux."},{"name":"Enracinés","text":"Les Sylvestres peuvent manipuler les plantes et la végétation environnantes, pour s''en servir comme d''armes ou pour piéger les intrus."},{"name":"Régénération naturelle","text":"À moins d''être entièrement réduit en cendres, un Sylvestre vaincu se régénère lentement et finit par recouvrer ses forces."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Troll' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Pourrisson', 'livre', 'wildkin', '{"source":"livre","page":255,"name":"Pourrisson","family":"wildkin","kind":"Défi · Sylvestre","quote":"","description":"Nés de la fusion de cadavres et de racines enchevêtrées, engendrés par la décomposition et la haine de la terre, les pourrissons rampent entre les arbres en traînant leur corps difforme, en quête incessante de chair.","track":8,"difficulty":{"force":2,"will":1,"influence":0,"reason":1,"precision":1,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"Le pourrisson libère un nuage de spores vénéneuses : tous les Parias cochent l''épuisement."},{"box":6,"text":"Le pourrisson se divise en plusieurs masses distinctes : le modificateur des tests de Précision et de Subterfuge augmente de +2."}],"complications":[{"text":"Se fond dans la végétation : il pourrait être n''importe où.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous écrase et vous vide de vos forces.","effect":"exhaustion","bookEffect":null},{"text":"Vous force à voir à quel point l''humanité a souillé son domaine.","effect":"shame","bookEffect":null},{"text":"Se révèle dans toute sa grandeur antique.","effect":"fear","bookEffect":null},{"text":"Emplit vos poumons de toxines psychotropes.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Détruit quelque chose qui vous est cher.","effect":"anger","bookEffect":"Anger"},{"text":"Se jette violemment sur vous.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Le pourrisson est pris de spasmes grotesques et rampe vers vous : le Paria qui vient d''agir coche la peur."},{"min":10,"text":"Le pourrisson fait surgir des racines qui s''enroulent autour de vos jambes : le Paria qui vient d''agir coche une blessure et doit réussir un test de Précision normal (5), sans quoi il ne pourra pas quitter sa position actuelle au prochain tour."},{"min":12,"text":"Le pourrisson fond en une masse informe et vous enveloppe : le Paria qui vient d''agir coche une blessure et doit réussir un test de Force normal (5), sans quoi, au début de son prochain tour, il doit réussir un nouveau test ou cocher une autre blessure."}]},"rules":[],"familyRules":[{"name":"Faiblesse face au feu","text":"Les Sylvestres craignent le feu et en souffrent plus que toute autre créature. L''utiliser réduit de 1 la difficulté de tous les tests contre eux."},{"name":"Enracinés","text":"Les Sylvestres peuvent manipuler les plantes et la végétation environnantes, pour s''en servir comme d''armes ou pour piéger les intrus."},{"name":"Régénération naturelle","text":"À moins d''être entièrement réduit en cendres, un Sylvestre vaincu se régénère lentement et finit par recouvrer ses forces."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Pourrisson' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Rancune ancestrale', 'livre', 'wildkin', '{"source":"livre","page":256,"name":"Rancune ancestrale","family":"wildkin","kind":"Défi · Sylvestre","quote":"","description":"Les rancunes ancestrales naissent de la profanation des lieux naturels. Elles infectent de nobles créatures, comme les grands cerfs, et les déforment horriblement pour en faire des gardiens d''une force et d''une endurance immenses.","track":10,"difficulty":{"force":2,"will":2,"influence":1,"reason":0,"precision":2,"subterfuge":0},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"La rancune ancestrale libère un nuage de spores vénéneuses : tous les Parias cochent l''épuisement."},{"box":6,"text":"La rancune ancestrale anime les arbres autour de vous, qui fouettent et frappent : tous les Parias doivent réussir un test de Précision difficile (6) ou cocher une blessure."},{"box":9,"text":"La rancune ancestrale active l''effet de dé d''obscurité de votre choix."}],"complications":[{"text":"Se fond dans la végétation : il pourrait être n''importe où.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous écrase et vous vide de vos forces.","effect":"exhaustion","bookEffect":null},{"text":"Vous force à voir à quel point l''humanité a souillé son domaine.","effect":"shame","bookEffect":null},{"text":"Se révèle dans toute sa grandeur antique.","effect":"fear","bookEffect":null},{"text":"Emplit vos poumons de toxines psychotropes.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Détruit quelque chose qui vous est cher.","effect":"anger","bookEffect":"Anger"},{"text":"Se jette violemment sur vous.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"La rancune ancestrale vous charge avec une violence écrasante : le Paria qui vient d''agir coche, à son choix, l''épuisement ou une blessure."},{"min":8,"text":"La rancune ancestrale fait surgir des racines qui s''enroulent autour de vos jambes : le Paria qui vient d''agir coche une blessure et doit réussir un test de Précision normal (5), sans quoi il ne pourra pas quitter sa position actuelle au prochain tour."},{"min":10,"text":"La rancune ancestrale pousse un cri, entre le brame et le hurlement d''une jeune fille : tous les Parias doivent réussir un test de Volonté difficile (6) ou cocher la peur."}]},"rules":[],"familyRules":[{"name":"Faiblesse face au feu","text":"Les Sylvestres craignent le feu et en souffrent plus que toute autre créature. L''utiliser réduit de 1 la difficulté de tous les tests contre eux."},{"name":"Enracinés","text":"Les Sylvestres peuvent manipuler les plantes et la végétation environnantes, pour s''en servir comme d''armes ou pour piéger les intrus."},{"name":"Régénération naturelle","text":"À moins d''être entièrement réduit en cendres, un Sylvestre vaincu se régénère lentement et finit par recouvrer ses forces."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Rancune ancestrale' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Bal de cour', 'livre', 'other', '{"source":"livre","page":259,"name":"Bal de cour","family":"other","kind":"Défi","quote":"","description":"Un bal de cour peut être un défi redoutable. Comme lors d''un duel, chaque détail et chaque geste comptent. Comme sur un champ de bataille, chaque décision peut faire basculer les alliances et changer le cours de la politique.","track":5,"difficulty":{"force":0,"will":0,"influence":1,"reason":1,"precision":0,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"Pendant le bal, vous êtes pris dans des futilités, comme des valses interminables ou des conversations parfaitement creuses : tous les Parias doivent réussir un test de Volonté, de Raison ou d''Influence normal (5) ou cocher l''insécurité (Confusion)."},{"box":5,"text":"Pendant le bal, vous atteignez votre but, mais s''il implique une alliance avec une personne présente au bal, celle-ci exigera quelque chose en retour."}],"complications":[{"text":"Pendant le bal, vous avez l''impression que chacun de vos gestes est jugé.","effect":"anger","bookEffect":"Anxiety"},{"text":"Pendant le bal, la longueur de la soirée sape votre volonté.","effect":"exhaustion","bookEffect":null},{"text":"Pendant le bal, vous êtes humilié devant des personnages importants.","effect":"shame","bookEffect":null},{"text":"Pendant le bal, vous craignez que vos véritables intentions aient été découvertes.","effect":"fear","bookEffect":null},{"text":"Pendant le bal, vous ne parvenez à deviner les véritables motivations de personne.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Pendant le bal, on vous toise avec dédain.","effect":"anger","bookEffect":"Anger"},{"text":"Pendant le bal, vous êtes victime d''un incident qui vous blesse.","effect":"wound","bookEffect":null}],"dark":{"when":"none","fromBox":null,"threshold":null,"rows":[]},"rules":[],"familyRules":[]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Bal de cour' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Duel', 'livre', 'other', '{"source":"livre","page":260,"name":"Duel","family":"other","kind":"Défi","quote":"","description":"Le duel est la plus personnelle des confrontations : un affrontement entre deux individus où chaque mouvement est chargé de tension. Les enjeux peuvent être élevés : l''honneur, la vengeance ou un pacte qui engage.","track":6,"difficulty":{"force":1,"will":1,"influence":1,"reason":0,"precision":1,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":1,"text":"Votre adversaire vous touche lors d''un échange rapproché : cochez une blessure."},{"box":3,"text":"Votre adversaire devient sérieux : la difficulté de tous les tests augmente de 1."},{"box":5,"text":"Votre adversaire tente de vous désarmer, et y parvient à moins que vous ne réussissiez un test de Précision normal (5)."}],"complications":[{"text":"Pendant le duel, votre adversaire maintient la pression.","effect":"anger","bookEffect":"Anxiety"},{"text":"Pendant le duel, la fatigue commence à se faire sentir.","effect":"exhaustion","bookEffect":null},{"text":"Pendant le duel, une erreur vous fait passer pour un débutant.","effect":"shame","bookEffect":null},{"text":"Pendant le duel, votre adversaire se révèle plus habile que prévu.","effect":"fear","bookEffect":null},{"text":"Pendant le duel, ses feintes vous font perdre votre concentration.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Pendant le duel, on vous provoque et vous perdez votre sang-froid.","effect":"anger","bookEffect":"Anger"},{"text":"Pendant le duel, vous êtes touché par une attaque précise.","effect":"wound","bookEffect":null}],"dark":{"when":"none","fromBox":null,"threshold":null,"rows":[]},"rules":["Conseil : Obscurité, mettez fin au défi à la 2e réussite si l''adversaire est inexpérimenté, à la 4e s''il est aguerri, ou à la 6e s''il est exceptionnel."],"familyRules":[]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Duel' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Enquête', 'livre', 'other', '{"source":"livre","page":261,"name":"Enquête","family":"other","kind":"Défi","quote":"","description":"Les préjugés, les mensonges et la méfiance sont des obstacles qu''un Gardien doit apprendre à surmonter. Au cours d''une enquête, on rassemble des indices, on interroge des témoins et l''on tente de donner un sens au chaos, en espérant que la vérité éclate.","track":4,"difficulty":{"force":0,"will":0,"influence":0,"reason":1,"precision":1,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[],"complications":[{"text":"Pendant l''enquête, vous craignez que la piste ne refroidisse.","effect":"anger","bookEffect":"Anxiety"},{"text":"Pendant l''enquête, il est difficile de rester concentré si longtemps.","effect":"exhaustion","bookEffect":null},{"text":"Pendant l''enquête, une erreur met votre compétence en doute.","effect":"shame","bookEffect":null},{"text":"Pendant l''enquête, vous prenez conscience du danger.","effect":"fear","bookEffect":null},{"text":"Pendant l''enquête, quelque chose ne colle pas.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Pendant l''enquête, un témoin vous tape vraiment sur les nerfs.","effect":"anger","bookEffect":"Anger"},{"text":"Pendant l''enquête, vous vous blessez par inadvertance.","effect":"wound","bookEffect":null}],"dark":{"when":"none","fromBox":null,"threshold":null,"rows":[]},"rules":["Conseil, complications créatives : lors d''une enquête, infliger des états ou des blessures peut compter moins que compliquer l''histoire. Une preuve essentielle, comme un parchemin ancien, peut être endommagée, ou les Parias peuvent s''apercevoir que le temps presse.","Conseil, la bonne décision : si les Parias font ce qu''il faut (par exemple, répandre de la poudre de fer froid là où une Fée est passée), cochez une réussite."],"familyRules":[]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Enquête' AND source = 'livre');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Igritte (Apocrypha)', 'apocrypha', 'other', '{"source":"apocrypha","page":29,"name":"Igritte (Apocrypha)","family":"other","kind":"Défi","quote":"","description":"Igritte est une combattante redoutable, déterminée à donner tout ce qu''elle a.","track":8,"difficulty":{"force":2,"will":1,"influence":1,"reason":0,"precision":2,"subterfuge":2},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"Igritte vous inflige une blessure par une contre-attaque."},{"box":4,"text":"Igritte lance une poudre qui vous pénètre dans les poumons. Chaque Paria doit réussir un test de Subterfuge (5) ou cocher l''épuisement et une blessure."},{"box":6,"text":"Igritte ne plaisante plus ! La difficulté de tous les tests augmente de 1."},{"box":8,"text":"Igritte cesse le combat sur l''ordre du Grand Maître ! Vous lisez de l''inquiétude et du regret dans ses yeux. Chaque Paria qui l''a blessée pendant le combat doit réussir un test de Volonté (5) ou cocher l''insécurité (Confusion)."}],"complications":[{"text":"Igritte semble déterminée à ne faire preuve d''aucune pitié.","effect":"anger","bookEffect":"Anxiety"},{"text":"Igritte vous impose son rythme jusqu''à l''épuisement.","effect":"exhaustion","bookEffect":null},{"text":"Igritte tente de cacher son trouble intérieur.","effect":"shame","bookEffect":null},{"text":"Igritte vous fixe d''un regard aussi froid que sa lame.","effect":"fear","bookEffect":null},{"text":"Igritte vous désoriente par ses feintes.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Igritte vous provoque jusqu''à ce que vous perdiez votre sang-froid.","effect":"anger","bookEffect":"Anger"},{"text":"Igritte frappe d''un coup vif et impitoyable.","effect":"wound","bookEffect":null}],"dark":{"when":"none","fromBox":null,"threshold":null,"rows":[]},"rules":["Si au moins deux Parias sont hors jeu, le Grand Maître interrompt l''épreuve en levant la main et en déclarant d''une voix forte : « Ça suffit ! »"],"familyRules":[]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Igritte (Apocrypha)' AND source = 'apocrypha');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Memento', 'apocrypha', 'shadows', '{"source":"apocrypha","page":37,"name":"Memento","family":"shadows","kind":"Défi · Ombre","quote":"","description":"Le Memento est une créature malveillante qui se tapit dans l''esprit de ceux qui ont été témoins d''événements horribles, se nourrissant de leurs sentiments et de leurs souvenirs les plus sombres. Parfois, ces créatures se libèrent et forcent les autres à revivre les souvenirs qu''elles ont dévorés, se repaissant de leur terreur.","track":5,"difficulty":{"force":0,"will":1,"influence":2,"reason":1,"precision":0,"subterfuge":0},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"Le Memento vous force à assister au premier meurtre de sang-froid commis par Frère Damien dans sa jeunesse. Chaque Paria doit réussir un test de Volonté (6) ou cocher la colère (Anxiety)."},{"box":5,"text":"Le Memento se dissipe dans un hurlement, faisant naître une vision dans vos esprits. Obscurité, passez à la scène suivante."}],"complications":[{"text":"Vous murmure sans cesse à l''oreille, nourrissant votre paranoïa.","effect":"anger","bookEffect":"Anxiety"},{"text":"Fait chuter la température et vous glace jusqu''aux os.","effect":"exhaustion","bookEffect":null},{"text":"Vous rappelle vos erreurs les plus douloureuses.","effect":"shame","bookEffect":null},{"text":"Se manifeste sous la forme de ce que vous craignez le plus.","effect":"fear","bookEffect":null},{"text":"Voile la réalité et brouille vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Se moque de vous et ricane depuis le néant d''où elle est venue.","effect":"anger","bookEffect":"Anger"},{"text":"Se matérialise en vrille et vous frappe.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Le Memento se glisse dans vos souvenirs et savoure les émotions qu''ils éveillent. Le Paria qui vient d''agir décrit un souvenir douloureux et décoche un état (que le Memento dévore), mais coche une blessure."},{"min":8,"text":"Le Memento déchaîne des tentacules vivants d''Obscurité qui vous frappent et vous broient. Chaque Paria doit réussir un test de Précision (4) ou cocher une blessure."},{"min":12,"text":"Le Memento vous force à assister au moment où Frère Damien a perdu la vue, ses yeux volés par une fée. Chaque Paria doit réussir un test de Volonté (6) ou cocher la peur."}]},"rules":["Agneau sacrificiel : tuer Frère Bernard ne demande qu''une seule réussite et met aussitôt fin au défi, déclenchant immédiatement la vision de Gabriel."],"familyRules":[{"name":"Sensibles à la verlume","text":"La verlume affaiblit les Ombres : elle réduit de 1 la difficulté de tous les tests contre elles."},{"name":"Froid, trop froid","text":"La température baisse en présence des Ombres, et chute brutalement quand elles gagnent en puissance."},{"name":"Informes","text":"Les Ombres n''ont que deux dimensions et peuvent se glisser par les fissures les plus étroites."},{"name":"Semi-solides","text":"Bien qu''elles n''aient pas de forme fixe, les Ombres restent tangibles : elles peuvent agir physiquement sur le monde, et le monde peut agir sur elles."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Memento' AND source = 'apocrypha');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Préparer l''antidote', 'apocrypha', 'other', '{"source":"apocrypha","page":45,"name":"Préparer l''antidote","family":"other","kind":"Défi","quote":"","description":"Précision, sang-froid et savoir : préparer un antidote en choisissant les bons ingrédients, en les dosant avec soin et en les mélangeant au moment juste peut sauver une vie… ou la condamner.","track":5,"difficulty":{"force":0,"will":0,"influence":0,"reason":1,"precision":1,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"Pendant la préparation de l''antidote, le poison vous saisit l''estomac et vous coupe le souffle. Tous les Parias doivent réussir un test de Force (5) ou cocher une blessure."},{"box":4,"text":"Pendant la préparation de l''antidote, les symptômes s''aggravent. Chaque Paria coche une blessure."}],"complications":[{"text":"Vous craignez d''avoir choisi le mauvais ingrédient ou le mauvais dosage.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vos mains tremblent, votre vue se brouille. Votre corps commence à lâcher.","effect":"exhaustion","bookEffect":null},{"text":"Vous renversez un ingrédient par terre. Les autres l''ont vu.","effect":"shame","bookEffect":null},{"text":"Vous comprenez que Noëlle ne vous aidera pas et vous laissera mourir.","effect":"fear","bookEffect":null},{"text":"Le poison provoque d''étranges hallucinations.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous vous sentez tourné en ridicule. Quel genre de leçon est-ce là ?","effect":"anger","bookEffect":"Anger"},{"text":"Une réaction inattendue libère des vapeurs corrosives sur votre peau.","effect":"wound","bookEffect":null}],"dark":{"when":"none","fromBox":null,"threshold":null,"rows":[]},"rules":[],"familyRules":[]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Préparer l''antidote' AND source = 'apocrypha');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Gardien revenant', 'apocrypha', 'fallen', '{"source":"apocrypha","page":47,"name":"Gardien revenant","family":"fallen","kind":"Défi · Déchu","quote":"","description":"L''esprit sans repos d''un ancien membre de l''Ordre, mort avec un serment inaccompli et un lien jamais rompu. Enfermé dans son cadavre à l''aide de généreuses quantités de salpêtre, il sert désormais de sujet d''étude à Lenoir.","track":5,"difficulty":{"force":1,"will":0,"influence":1,"reason":1,"precision":1,"subterfuge":0},"resistances":[],"vulnerabilities":[],"triggers":[{"box":4,"text":"Le Gardien revenant brise ses chaînes et s''échappe. Les avait-on laissées lâches exprès ?"},{"box":5,"text":"La chouette devient folle dans sa cage. Si les Parias ne la libèrent pas dans le tour, elle meurt en se fracassant contre les barreaux."}],"complications":[{"text":"Vous force à revivre son tourment en visions.","effect":"anger","bookEffect":"Anxiety"},{"text":"Murmure sans fin à vos oreilles.","effect":"exhaustion","bookEffect":null},{"text":"Apparaît sous les traits d''un être que vous avez perdu.","effect":"shame","bookEffect":null},{"text":"Fait passer sur vous le frisson de la mort, qui vous fait trembler.","effect":"fear","bookEffect":null},{"text":"Possède votre corps un bref instant.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous accuse de crimes que vous n''avez pas commis.","effect":"anger","bookEffect":"Anger"},{"text":"Vous lance des objets avec une force violente.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Le Gardien revenant fait surgir dans vos esprits des images de sa propre mort. Tous les Parias doivent réussir un test de Volonté (5) ou cocher la colère (Anxiety)."},{"min":9,"text":"Le Gardien revenant fait voler des objets qui foncent sur vous ! Tous les Parias doivent réussir un test de Précision (5) ou cocher une blessure."}]},"rules":["Lien : la chouette est le véritable lien ; c''était le seul ami du gardien. Libérer la chouette de sa cage libère aussi l''esprit du Gardien revenant, qui disparaît à jamais. Tuer la chouette a le même effet, mais avant de disparaître, le Gardien revenant hurle son tourment : tous les Parias doivent réussir un test de Volonté (7) ou cocher la peur.","Sous observation : outre Lenoir, toute la classe observe les Parias. Utilisez les complications pour imposer la honte ou la colère (Anxiety), causées par des regards méprisants, des rires ou des insultes chuchotées."],"familyRules":[{"name":"Éthérés","text":"Les Déchus passent d''une forme physique à une forme intangible. Intangibles, ils traversent la matière : on ne peut pas les toucher, et ils ne peuvent pas vous toucher. Quand ils prennent une forme physique (en possédant un cadavre ou au contact du salpêtre), ils deviennent tangibles."},{"name":"Sensibles au salpêtre","text":"Exposé à la poudre de salpêtre, un Déchu intangible est forcé de se manifester sous forme physique."},{"name":"Affaire inachevée","text":"Chaque Déchu est retenu dans le monde des vivants par une affaire non résolue. La résoudre le fait disparaître aussitôt."},{"name":"Liés","text":"Les Déchus sont ancrés à un lieu ou à un objet précis. Si l''objet est détruit, le Déchu disparaît aussitôt."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Gardien revenant' AND source = 'apocrypha');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Le voyage', 'apocrypha', 'other', '{"source":"apocrypha","page":53,"name":"Le voyage","family":"other","kind":"Défi","quote":"","description":"Survivre dans les étendues sauvages d''Egas n''a rien d''aisé. Entre le froid mordant, la végétation tordue par l''Obscurité et les dangers tapis, un seul faux pas pourrait coûter cher à tout le groupe.","track":6,"difficulty":{"force":1,"will":1,"influence":0,"reason":1,"precision":1,"subterfuge":0},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"Pendant la traversée de la forêt, vous tombez sur le cadavre d''une recrue d''une autre expédition. Tous les Parias doivent réussir un test de Volonté (6) ou cocher la colère (Anxiety) ou la peur."},{"box":4,"text":"Pendant la traversée de la forêt, vous croisez un groupe de cadets en difficulté : les aider augmente de 1 la difficulté de vos prochains tests. Les abandonner à leur sort fait cocher la honte à tous les Parias."},{"box":5,"text":"Pendant la traversée de la forêt, le sol se dérobe soudain sous vos pieds et vous glissez contre une paroi de rochers acérés. Tous les Parias cochent une blessure."}],"complications":[{"text":"Les cris d''animaux à l''agonie parviennent à vos oreilles.","effect":"anger","bookEffect":"Anxiety"},{"text":"Le froid mordant engourdit vos membres.","effect":"exhaustion","bookEffect":null},{"text":"Vous ralentissez vos compagnons de route.","effect":"shame","bookEffect":null},{"text":"Vous trouvez les restes d''un animal dévoré, peut-être par un nuisible.","effect":"fear","bookEffect":null},{"text":"Vous avez l''impression d''avoir déjà emprunté ce chemin.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous pensez à Célestine, qui attend bien au chaud.","effect":"anger","bookEffect":"Anger"},{"text":"Vous trébuchez sur une racine noueuse et vous entaillez méchamment.","effect":"wound","bookEffect":null}],"dark":{"when":"none","fromBox":null,"threshold":null,"rows":[]},"rules":[],"familyRules":[]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Le voyage' AND source = 'apocrypha');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Le vol de la plume', 'apocrypha', 'other', '{"source":"apocrypha","page":56,"name":"Le vol de la plume","family":"other","kind":"Défi","quote":"","description":"S''infiltrer dans un lieu interdit, distraire quiconque monte la garde, forcer une vitrine et dérober une relique, le tout sans être vu. Facile, non ?","track":6,"difficulty":{"force":0,"will":0,"influence":0,"reason":1,"precision":1,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[],"complications":[{"text":"Vous vous rendez compte que vous êtes à deux doigts d''être vu.","effect":"anger","bookEffect":"Anxiety"},{"text":"La tension permanente vous use.","effect":"exhaustion","bookEffect":null},{"text":"Vous vous sentez comme un voleur. Vous ne devriez pas être ici.","effect":"shame","bookEffect":null},{"text":"Vous vous demandez ce qui arriverait si vous étiez pris.","effect":"fear","bookEffect":null},{"text":"Le plan de l''église vous désoriente.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous surprenez des remarques méprisantes sur vos semblables.","effect":"anger","bookEffect":"Anger"},{"text":"Vous vous blessez en tentant maladroitement de ne pas être découvert.","effect":"wound","bookEffect":null}],"dark":{"when":"none","fromBox":null,"threshold":null,"rows":[]},"rules":["Sur le fil du rasoir : si les Parias accumulent 6 réussites avant 6 complications, ils réussissent leur coup. En revanche, s''ils atteignent 6 complications avant d''obtenir 6 réussites, ils sont découverts et emprisonnés."],"familyRules":[]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Le vol de la plume' AND source = 'apocrypha');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Marcheval de Corville', 'apocrypha', 'hexed', '{"source":"apocrypha","page":66,"name":"Marcheval de Corville","family":"hexed","kind":"Défi · Maudit","quote":"","description":"Marcheval semble disposé à parler, mais peut-être se joue-t-il simplement des Parias. Pendant l''interrogatoire, il usera de ses pouvoirs pour leur nuire, les faire douter d''eux-mêmes et semer l''incertitude dans leur cœur.","track":6,"difficulty":{"force":0,"will":1,"influence":1,"reason":1,"precision":0,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"Marcheval avoue aux Parias que Vilàr lui a ordonné d''infiltrer la cour d''Aurenbourg pour découvrir où se trouve le Cœur d''Aurélie. Chaque Paria coche l''insécurité (Confusion), la colère (Anxiety) ou la peur (au choix)."},{"box":5,"text":"Marcheval se libère de ses chaînes en se broyant les mains. Même encerclé, il ne montre aucune peur et tente de vous frapper de giclées de son sang. Tous les Parias doivent réussir un test de Précision (5) ou cocher une blessure."},{"box":6,"text":"Marcheval hurle que tout espoir est perdu : son maître a envoyé Velmire, son infant, conquérir la Citadelle de l''Aube cendrée, et il est désormais trop tard pour intervenir. Puis il maudit un Paria choisi par l''Obscurité et se donne la mort. L''Obscurité gagne une complication qu''elle pourra utiliser contre ce Paria plus tard, quand elle le souhaite."}],"complications":[{"text":"Vous jette un mauvais œil qui vous promet une vie de souffrance.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous inflige un maléfice qui vous laisse faible et malade.","effect":"exhaustion","bookEffect":null},{"text":"Voit votre culpabilité et vous convainc que les autres ne voient qu''elle en vous.","effect":"shame","bookEffect":null},{"text":"Vous prédit un terrible présage.","effect":"fear","bookEffect":null},{"text":"Brouille vos sens.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous rappelle que votre destin est scellé et que vous en êtes l''esclave.","effect":"anger","bookEffect":"Anger"},{"text":"Attire sur vous un événement désastreux.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Marcheval murmure dans une langue gutturale et dissonante qui vous donne mal à la tête. Tous les Parias doivent réussir un test de Volonté (5) ou cocher l''insécurité (Confusion)."},{"min":9,"text":"Marcheval invoque une nuée de corbeaux, certains noirs, d''autres blancs, qui fondent dans la cathédrale en brisant les vitraux et vous attaquent. Tous les Parias doivent réussir un test de Précision ou de Force (5) ou cocher une blessure."}]},"rules":[],"familyRules":[{"name":"Vulnérables aux symboles sacrés","text":"Les Maudits abhorrent les symboles sacrés de toute sorte, pas seulement ceux du luminarisme, pourvu qu''ils aient été créés par de vrais croyants. Quand ils y sont exposés, la difficulté de tous les tests contre eux est réduite de 1."},{"name":"Aura de ruine","text":"La présence d''un Maudit attire le mauvais sort. Tout ce qui peut mal tourner tourne mal, de la pire façon possible. Égaler la difficulté d''un test contre un Maudit ne donne pas une réussite avec complication, mais seulement une complication."},{"name":"Destin marqué","text":"Vous pouvez mettre de côté jusqu''à 3 complications causées par des tests contre un Maudit et les faire jouer plus tard, quand vous le souhaitez."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Marcheval de Corville' AND source = 'apocrypha');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'L''évasion du donjon', 'apocrypha', 'other', '{"source":"apocrypha","page":83,"name":"L''évasion du donjon","family":"other","kind":"Défi","quote":"","description":"Tandis que l''armée de Velmire prend d''assaut le donjon, les Parias s''échappent par le passage secret qui les y a menés, emmenant Ophelia avec eux pour l''éloigner du conflit.","track":4,"difficulty":{"force":0,"will":1,"influence":0,"reason":1,"precision":0,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"Pendant l''évasion, Ophelia trébuche et se tord la cheville. La difficulté des tests suivants augmente de 1 jusqu''à ce qu''un Paria obtienne une réussite à un test normal (5) pour l''aider."},{"box":3,"text":"Pendant l''évasion, les cris qui montent du donjon sont terribles. Tous les Parias doivent réussir un test de Volonté (6) ou cocher la honte et la colère (Anger)."},{"box":4,"text":"Pendant l''évasion, Velmire vous attend à la sortie, déjà blessé mais toujours dangereux. « On dirait que je vous ai débusqués, petites souris », murmure-t-il. Affrontez un Sang-Noble (Nobleblood, p. 249 du livre de base), en considérant les trois premières cases de progression comme déjà cochées."}],"complications":[{"text":"Un effondrement soudain vous oblige à trouver un autre chemin.","effect":"anger","bookEffect":"Anxiety"},{"text":"La course effrénée dans la poussière et l''obscurité est épuisante.","effect":"exhaustion","bookEffect":null},{"text":"Vous entendez les cris des soldats que vous avez laissés derrière vous.","effect":"shame","bookEffect":null},{"text":"L''armée de Velmire perce les défenses et envahit le donjon.","effect":"fear","bookEffect":null},{"text":"Ce chemin ne ressemble pas à celui que vous avez pris à l''aller.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous entendez Velmire rire, se délectant du carnage.","effect":"anger","bookEffect":"Anger"},{"text":"Une explosion fait pleuvoir des rochers sur vous.","effect":"wound","bookEffect":null}],"dark":{"when":"none","fromBox":null,"threshold":null,"rows":[]},"rules":[],"familyRules":[]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'L''évasion du donjon' AND source = 'apocrypha');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Henry des Crêtes', 'apocrypha', 'ferals', '{"source":"apocrypha","page":107,"name":"Henry des Crêtes","family":"ferals","kind":"Défi · Polymorphe","quote":"","description":"Henry veut mourir, mais son instinct ne le laisse pas abandonner. Sa chair est affaiblie par l''argent. Il n''en reste pas moins un Polymorphe, et l''un des chasseurs les plus habiles que Valnord ait jamais connus.","track":8,"difficulty":{"force":2,"will":2,"influence":0,"reason":0,"precision":1,"subterfuge":1},"resistances":[],"vulnerabilities":[],"triggers":[{"box":3,"text":"Henry pousse un son à mi-chemin entre le cri et le grondement. Tous les Parias doivent réussir un test de Volonté (5) ou cocher la peur."},{"box":6,"text":"Henry soulève un Paria et le projette contre un autre avec une force brutale. Tous deux cochent une blessure."}],"complications":[{"text":"Est aveuglé par la rage et impossible à prévoir.","effect":"anger","bookEffect":"Anxiety"},{"text":"Vous plaque violemment au sol ; vous vous sentez engourdi.","effect":"exhaustion","bookEffect":null},{"text":"Croise un instant votre regard avec une expression humaine et terrifiée.","effect":"shame","bookEffect":null},{"text":"Vous regarde comme un morceau de viande.","effect":"fear","bookEffect":null},{"text":"Se déplace trop vite pour que vous puissiez le suivre.","effect":"insecurity","bookEffect":"Confusion"},{"text":"Vous traque sans relâche, jusqu''à ce que votre instinct de survie prenne le dessus.","effect":"anger","bookEffect":"Anger"},{"text":"Déchire votre chair de ses crocs et de ses griffes.","effect":"wound","bookEffect":null}],"dark":{"when":"always","fromBox":null,"threshold":null,"rows":[{"min":6,"text":"Henry rend coup pour coup sans vous laisser le temps de souffler. Le Paria qui vient d''agir coche l''épuisement."},{"min":8,"text":"Henry se jette sur vous dans un tourbillon de crocs et de griffes. Le Paria qui vient d''agir coche la peur et une blessure."},{"min":12,"text":"Henry vous mord et vous retient entre ses mâchoires. Le Paria qui vient d''agir coche une blessure et doit réussir un test de Force (5) pour se dégager ; sinon, à son prochain tour, il doit refaire un test pour éviter une autre blessure."}]},"rules":["Blessé par l''argent : l''argent fondu dans la chair d''Henry l''empêche de guérir. Henry ne régénère donc aucune blessure, pas même celles infligées par des armes ordinaires."],"familyRules":[{"name":"Vulnérables à l''argent","text":"L''argent est le seul métal capable d''infliger des blessures qu''un Polymorphe ne peut pas régénérer. En outre, la difficulté des tests visant à blesser un Polymorphe avec une arme d''argent ou d''argentacier est réduite de 1."},{"name":"Régénération","text":"Les Polymorphes guérissent rapidement de toute blessure infligée par une arme ordinaire. À la fin de chaque tour, effacez toutes les blessures causées par ces armes. Les blessures dues à l''argent, à l''argentacier, aux dons et aux sombres héritages ne se régénèrent jamais."},{"name":"Rage","text":"Sous leur forme bestiale, les Polymorphes agissent en purs prédateurs. Impossible de raisonner avec eux : tout test visant à les raisonner entraîne automatiquement une complication."}]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Henry des Crêtes' AND source = 'apocrypha');
INSERT INTO challenges (name, source, family, sheet)
    SELECT 'Gabriel', 'apocrypha', 'other', '{"source":"apocrypha","page":111,"name":"Gabriel","family":"other","kind":"Défi","quote":"","description":"Gabriel est déterminé à accomplir sa mission : il combattra quiconque tentera de se dresser sur son chemin. Ceux qui ne font pas partie de la solution font partie du problème ; il peut toujours recommencer et chercher d''autres Parias.","track":12,"difficulty":{"force":2,"will":0,"influence":2,"reason":0,"precision":2,"subterfuge":2},"resistances":[],"vulnerabilities":[],"triggers":[{"box":2,"text":"Gabriel contre-attaque, vif comme un serpent. Le Paria qui vient d''agir coche une blessure."},{"box":4,"text":"Gabriel lance un dispositif qui libère une fumée blanchâtre. Tous les Parias doivent réussir un test de Subterfuge (6) ou cocher l''insécurité (Confusion)."},{"box":6,"text":"Gabriel vous plante dans la jambe une seringue de rêverie modifiée. Le Paria qui vient d''agir doit réussir un test de Force (6), sinon il ne peut plus utiliser ses dons jusqu''à la fin de la scène."},{"box":8,"text":"Gabriel vous presse d''une série de feintes. Le Paria qui vient d''agir coche l''épuisement et doit réussir un test de Précision (6) ou cocher une blessure."},{"box":10,"text":"Gabriel vous supplie d''être raisonnables : il croit en vous, pourquoi refusez-vous de l''écouter ? Tous les Parias doivent réussir un test de Raison (6) ou cocher la colère (Anger)."},{"box":11,"text":"Gabriel vous asperge d''une substance psychotrope. Tous les Parias doivent réussir un test de Subterfuge (7) ou cocher la colère (Anxiety), la peur et l''insécurité (Confusion)."},{"box":12,"text":"Dans un dernier souffle, Gabriel vous demande de sauver le destin d''Egas. Chaque Paria qui l''estime juste coche la honte pour avoir tué Gabriel."}],"complications":[],"dark":{"when":"none","fromBox":null,"threshold":null,"rows":[]},"rules":["Si les Parias ont suivi le conseil de Sophie pendant « Intrigue à Aurenbourg » (p. 101), ils peuvent s''en servir pour obtenir l''avantage sur un seul test. Ensuite, Gabriel ne se laisse plus prendre à la ruse."],"familyRules":[]}'
    WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE name = 'Gabriel' AND source = 'apocrypha');

-- ── PNJ (documentations/spec_pnj.md §6.2) ─────────────────────────────────────
-- npcs : bibliothèque du MJ (PNJ, monstres, animaux) ; system_data propre au slug.
-- session_npcs : PNJ présents à une table, copie de la fiche (sheet) + état du slug.
create table if not exists npcs
(
    id          INTEGER
        primary key autoincrement,
    prenom      TEXT,
    nom         TEXT                 not null,
    role        TEXT,
    description TEXT,
    gm_notes    TEXT,
    tags        TEXT     default '[]' not null,
    avatar      TEXT,
    icon        TEXT,
    source      TEXT,
    page        INTEGER,
    system_data TEXT     default '{}' not null,
    created_at  DATETIME default CURRENT_TIMESTAMP,
    updated_at  DATETIME default CURRENT_TIMESTAMP
);

create index if not exists idx_npcs_nom
    on npcs (nom);

create table if not exists session_npcs
(
    id         INTEGER
        primary key autoincrement,
    session_id INTEGER              not null
        references game_sessions
            on delete cascade,
    npc_id     INTEGER
        references npcs
            on delete set null,
    name       TEXT                 not null,
    sheet      TEXT     default '{}' not null,
    state      TEXT     default '{}' not null,
    notes      TEXT,
    sort_order INTEGER  default 0    not null,
    created_at DATETIME default CURRENT_TIMESTAMP
);

create index if not exists idx_session_npcs_session_id
    on session_npcs (session_id);
